insert into loja.categories (id, slug, name, description, image, position) values ('volta-18k', 'volta-18k', 'Volta 18K', 'Pré-venda Edição Pampulha. Duas peças, 200 unidades: camiseta de algodão e regata cropped. From: Dry Lake, to: all over the world.', '/img/produtos/c1-cropped-preta-duo-1600.webp', 0) on conflict (id) do update set name = excluded.name, description = excluded.description, image = excluded.image, position = excluded.position;
