insert into loja.products (id, slug, name, subtitle, description, category_slug, price_cents, compare_at_cents, badges, tags, featured, highlights, details, care, position, status) values ('camiseta-letz-bora-algodao', 'camiseta-letz-bora-algodao', 'Camiseta LETZ BORA', 'Volta 18K · Algodão', 'Camiseta preta de algodão para o dia a dia de quem corre. Na frente, o BORA pequeno. Nas costas, o selo LETZ BORA: running is a lifestyle, beyond the pace. Na barra, as coordenadas de onde a gente sai, em BH, e para onde vai: FROM: DRY LAKE, TO: ALL OVER THE WORLD.', 'camisetas', 10000, null, array['Pré-venda','Volta 18K']::text[], array['lifestyle','volta-18k','pre-venda','algodao']::text[], true, array['Algodão macio','Selo LETZ BORA nas costas','Coordenadas na barra','Para treinar e para depois']::text[], '[{"label":"Tecido","value":"Algodão"},{"label":"Modelagem","value":"Regular, unissex"},{"label":"Estampa frente","value":"BORA, em branco"},{"label":"Estampa costas","value":"Selo LETZ BORA em branco e verde neon"}]'::jsonb, 'Lavar do avesso em água fria. Não usar alvejante. Secar à sombra. Não passar ferro sobre as estampas.', -2, 'active') on conflict (id) do update set status = excluded.status;
