insert into loja.products (id, slug, name, subtitle, description, category_slug, price_cents, compare_at_cents, badges, tags, featured, highlights, details, care, position, status) values ('regata-cropped-bora', 'regata-cropped-bora', 'Regata Cropped BORA', 'Volta 18K · Performance', 'Regata cropped preta em tecido performance, leve e de secagem rápida. BORA em verde neon no peito, coordenadas da Pampulha na barra e, nas costas, as curvas de nível da marca em volta do raio. Para o treino e para o pós-treino.', 'regatas', 12000, null, array['Pré-venda','Volta 18K']::text[], array['corrida','volta-18k','pre-venda','feminino','cropped']::text[], true, array['Tecido performance','Secagem rápida','Curvas de nível nas costas','Estampa verde neon']::text[], '[{"label":"Tecido","value":"Performance fabric, quick dry"},{"label":"Modelagem","value":"Cropped, justa"},{"label":"Cor","value":"Preta com estampa verde neon"},{"label":"Estampa frente","value":"BORA no peito e coordenadas na barra"},{"label":"Estampa costas","value":"Curvas de nível com o raio BORA"}]'::jsonb, 'Lavar à mão ou na máquina em água fria. Não usar amaciante (tira o efeito de secagem rápida). Secar à sombra.', -1, 'active') on conflict (id) do update set status = excluded.status;
