insert into loja.products (id, slug, name, subtitle, description, category_slug, price_cents, compare_at_cents, badges, tags, featured, highlights, details, care, position, status) values ('camiseta-dri-fit-bora', 'camiseta-dri-fit-bora', 'Camiseta Dri-Fit BORA', 'A camiseta oficial do movimento', 'Tecido dri-fit leve que tira o suor da pele e seca rápido. Na frente, o BORA discreto. Nas costas, o grito: letz BORAAA!! Corte reto, gola careca e as curvas de nível da marca subindo pela barra.', 'camisetas', 14900, null, array['Lançamento']::text[], array['corrida','essenciais','drop-2026']::text[], true, array['Seca rápido','Leve e respirável','letz BORAAA!! nas costas','Etiqueta sem costura']::text[], '[{"label":"Tecido","value":"Poliéster dri-fit com toque macio"},{"label":"Modelagem","value":"Regular, unissex"},{"label":"Estampa","value":"Silk de alta durabilidade"},{"label":"Origem","value":"Feita no Brasil"}]'::jsonb, 'Lavar à mão ou na máquina em água fria, do avesso. Não usar alvejante nem amaciante. Secar à sombra. Não passar ferro na estampa.', 1, 'draft') on conflict (id) do update set status = excluded.status;
