insert into loja.products (id, slug, name, subtitle, description, category_slug, price_cents, compare_at_cents, badges, tags, featured, highlights, details, care, position, status) values ('corta-vento-bora', 'corta-vento-bora', 'Corta-vento BORA', 'Para o treino das 5h', 'Corta-vento leve com capuz, recortes em preto, branco e verde neon e o escudo bordado no peito. Bloqueia o vento, aguenta garoa fina e dobra pequeno para ir na mochila. Na manga, o BORAAA!! que todo mundo reconhece na largada.', 'agasalhos', 38900, null, array['Lançamento']::text[], array['corrida','drop-2026']::text[], true, array['Bloqueia o vento','Repele garoa fina','Capuz com regulagem','Punhos e barra com elástico']::text[], '[{"label":"Tecido","value":"Tactel leve com acabamento repelente"},{"label":"Fechamento","value":"Zíper frontal completo"},{"label":"Bolsos","value":"Dois bolsos laterais"},{"label":"Modelagem","value":"Regular, unissex"}]'::jsonb, 'Lavar à mão em água fria. Não torcer. Secar à sombra, pendurado. Não usar secadora.', 2, 'draft') on conflict (id) do update set status = excluded.status;
