insert into loja.products (id, slug, name, subtitle, description, category_slug, price_cents, compare_at_cents, badges, tags, featured, highlights, details, care, position, status) values ('macaquinho-tri-bora', 'macaquinho-tri-bora', 'Macaquinho Tri BORA', 'Nada, pedala e corre', 'Macaquinho de triathlon com manga curta, zíper nas costas e forro de secagem rápida. As curvas de nível da marca na frente e as três faixas neon na coluna. Feito para a prova inteira, da largada na água até a chegada.', 'triathlon', 54900, null, array['Triathlon']::text[], array['triathlon','drop-2026']::text[], true, array['Forro de secagem rápida','Zíper nas costas','Barra com silicone','Tecido com compressão leve']::text[], '[{"label":"Tecido","value":"Lycra técnica com compressão leve"},{"label":"Forro","value":"Espuma fina de triathlon"},{"label":"Fechamento","value":"Zíper traseiro"},{"label":"Modelagem","value":"Justa"}]'::jsonb, 'Enxaguar em água doce logo após o uso, principalmente depois de piscina ou mar. Lavar à mão. Secar à sombra.', 3, 'draft') on conflict (id) do update set status = excluded.status;
