insert into loja.products (id, slug, name, subtitle, description, category_slug, price_cents, compare_at_cents, badges, tags, featured, highlights, details, care, position, status) values ('bone-five-panel-bora', 'bone-five-panel-bora', 'Boné Five Panel BORA', 'Leve, com aba flexível', 'Five panel de corrida, leve e com aba flexível que dobra sem marcar. BORA em verde neon na frente e as curvas de nível da marca na lateral. Regulagem traseira para qualquer cabeça.', 'acessorios', 13900, null, array[]::text[], array['corrida','essenciais']::text[], true, array['Ultraleve','Aba flexível','Regulagem traseira','Faixa interna que absorve suor']::text[], '[{"label":"Tecido","value":"Poliéster técnico"},{"label":"Tamanho","value":"Único, ajustável"},{"label":"Aba","value":"Flexível, dobrável"}]'::jsonb, 'Lavar à mão com sabão neutro. Não colocar na máquina. Secar à sombra.', 4, 'draft') on conflict (id) do update set status = excluded.status;
